#include "esp_camera.h"
#include "soc/soc.h"
#include "soc/rtc_cntl_reg.h"
#include <WiFi.h>
#include <WebServer.h>

// НАСТРОЙКА WI-FI (укажите свои данные или оставьте для точки доступа)
const char* ssid = "ESP32-Camera";
const char* password = "12345678";

WebServer server(80);

// Конфигурация пинов (ваша схема)
#define CAMERA_PIN_PWDN    -1
#define CAMERA_PIN_RESET   -1
#define CAMERA_PIN_XCLK    18
#define CAMERA_PIN_SIOD    4
#define CAMERA_PIN_SIOC    12
#define CAMERA_PIN_D7      32
#define CAMERA_PIN_D6      27
#define CAMERA_PIN_D5      35
#define CAMERA_PIN_D4      23
#define CAMERA_PIN_D3      26
#define CAMERA_PIN_D2      33
#define CAMERA_PIN_D1      25
#define CAMERA_PIN_D0      34
#define CAMERA_PIN_VSYNC   19
#define CAMERA_PIN_HREF    -1  // ВНИМАНИЕ: без HREF изображение может косить или не работать!
#define CAMERA_PIN_PCLK    21

// Функция отправки кадра в браузер
void handle_jpg() {
  camera_fb_t * fb = esp_camera_fb_get();
  if (!fb) {
    server.send(500, "text/plain", "Кадр не захвачен");
    return;
  }

  // Если камера настроена на выдачу JPEG
  if (fb->format == PIXFORMAT_JPEG) {
    server.sendHeader("Content-Disposition", "inline; filename=capture.jpg");
    server.sendHeader("Access-Control-Allow-Origin", "*");
    server.setContentLength(fb->len);
    server.send(200, "image/jpeg", "");
    WiFiClient client = server.client();
    client.write(fb->buf, fb->len);
  } else {
    // Если OV7670 выдает YUV/RGB (без сжатия), конвертируем в BMP прямо «на лету»
    uint8_t * buf = NULL;
    size_t buf_len = 0;
    bool converted = frame2bmp(fb, &buf, &buf_len);
    if(!converted){
       server.send(500, "text/plain", "Ошибка конвертации в BMP");
       esp_camera_fb_return(fb);
       return;
    }
    server.sendHeader("Content-Disposition", "inline; filename=capture.bmp");
    server.setContentLength(buf_len);
    server.send(200, "image/bmp", "");
    WiFiClient client = server.client();
    client.write(buf, buf_len);
    free(buf); // Освобождаем временный буфер BMP
  }

  esp_camera_fb_return(fb);
}

void setup() {
  WRITE_PERI_REG(RTC_CNTL_BROWN_OUT_REG, 0); 
  Serial.begin(115200);

  camera_config_t config;
  config.ledc_channel = LEDC_CHANNEL_0;
  config.ledc_timer = LEDC_TIMER_0;
  config.pin_d0 = CAMERA_PIN_D0;
  config.pin_d1 = CAMERA_PIN_D1;
  config.pin_d2 = CAMERA_PIN_D2;
  config.pin_d3 = CAMERA_PIN_D3;
  config.pin_d4 = CAMERA_PIN_D4;
  config.pin_d5 = CAMERA_PIN_D5;
  config.pin_d6 = CAMERA_PIN_D6;
  config.pin_d7 = CAMERA_PIN_D7;
  config.pin_xclk = CAMERA_PIN_XCLK;
  config.pin_pclk = CAMERA_PIN_PCLK;
  config.pin_vsync = CAMERA_PIN_VSYNC;
  config.pin_href = CAMERA_PIN_HREF;
  config.pin_sccb_sda = CAMERA_PIN_SIOD;
  config.pin_sccb_scl = CAMERA_PIN_SIOC;
  config.pin_pwdn = CAMERA_PIN_PWDN;
  config.pin_reset = CAMERA_PIN_RESET;
  config.xclk_freq_hz = 10000000; // Для OV7670 без FIFO лучше снизить до 10MHz для стабильности

  // OV7670 без FIFO редко умеет в аппаратный JPEG. Ставим YUV422 или GRAYSCALE
  config.pixel_format = PIXFORMAT_GRAYSCALE; 
  config.frame_size = FRAMESIZE_QVGA; // 320x240
  config.fb_count = 1;

  if (esp_camera_init(&config) != ESP_OK) {
    Serial.println("Ошибка камеры!");
    return;
  }

  // Создаем собственную Wi-Fi сеть
  WiFi.softAP(ssid, password);
  Serial.print("Wi-Fi сеть создана. IP-адрес ESP32: ");
  Serial.println(WiFi.softAPIP());

  // Настраиваем адрес страницы
  server.on("/cam", handle_jpg);
  server.begin();
}

void loop() {
  server.handleClient(); // Ожидаем запросов от браузера
}
